		/** Visibility choice, owned by the Settings row and read by the mount. */
		const ENABLED_KEY = "@vfvrpq/dsh-pinned-sessions.enabled";
		function readEnabled() {
			try {
				return window.localStorage?.getItem(ENABLED_KEY) !== "false";
			} catch {
				return true;
			}
