ocument.head.appendChild(tag);\n\t\t}\n\t\t//#endregion\n\t\t//#region dictionaries\n\t\t/** Simplified Chinese copy — the key-set source of truth. */\n\t\tconst zh = {\n\t\t\t\"section.title\": \"置顶\",\n\t\t\t\"section.aria\": \"置顶会话\",\n\t\t\t\"section.count\": \"{count}\",\n\t\t\t\"section.countFiltered\": \"{matched}/{count}\",\n\t\t\t\"section.hint\": \"在会话行上点图钉即可置顶\",\n\t\t\t\"section.noMatch\": \"没有匹配的置顶会话\",\n\t\t\t\"section.note.archived\": \"另有 {count} 个已归档的置顶会话未在此显示\",\n\t\t\t\"section.collapse\": \"收起置顶会话\",\n\t\t\t\"section.expand\": \"展开置顶会话\",\n\t\t\t\"search.open\": \"搜索置顶会话\",\n\t\t\t\"search.placeholder\": \"搜索置顶会话\",\n\t\t\t\"search.close\": \"关闭搜索\",\n\t\t\t\"chip.open\": \"在 npm 上打开 {name} v{version}\",\n\t\t\t\"row.unread\": \"待查看\",\n\t\t\t\"row.schedule\": \"{count} 个自动化任务\",\n\t\t\t\"row.pinned\": \"已置顶\",\n\t\t\t\"setting.title\": \"置顶会话区\",\n\t\t\t\"setting.description\": \"在侧栏「工作区」列表顶部显示置顶会话分组。\",\n\t\t\t\"actions.pin\": \"置顶会话\",\n\t\t\t\"actions.unpin\": \"取消置顶\",\n\t\t\t\"actions.archive\": \"归档会话\",\n\t\t\t\"menu.pinSession\": \"置顶会话\",\n\t\t\t\"menu.unpinSession\": \"取消置顶\",\n\t\t\t\"menu.archiveSession\": \"归档会话\",\n\t\t\t\"row.open\": \"打开会话“{title}”\",\n\t\t\t\"row.running\": \"进行中\",\n\t\t\t\"row.waitingApproval\": \"等待审批\",\n\t\t\t\"row.planReview\": \"计划待审\",\n\t\t\t\"row.waitingAnswer\": \"等待回答\",\n\t\t\t\"status.compact.approval\": \"待审批\",\n\t\t\t\"status.compact.planReview\": \"计划待审\",\n\t\t\t\"status.compact.answer\": \"待回答\",\n\t\t\t\"row.untitled\": \"未命名会话\",\n\t\t\t/* Relative-time vocabulary is the native sidebar's, verbatim. */\n\t\t\t\"time.now\": \"刚刚\",\n\t\t\t\"time.minutes\": \"{n}分钟\",\n\t\t\t\"time.hours\": \"{n}小时\",\n\t\t\t\"time.days\": \"{n}天\",\n\t\t\t\"time.months\": \"{n}个月\",\n\t\t\t\"time.years\": \"{n}年\",\n\t\t\t\"time.ago\": \"{t}前\"\n\t\t};\n\t\t/** English copy, same key set. */\n\t\tconst en = {\n\t\t\t\"section.title\": \"Pinned\",\n\t\t\t\"section.aria\": \"Pinned sessions\",\n\t\t\t\"section.